function showQualificationForm(returnEditor=false){const q=qualificationRecord;modal('专项资质申请',`<span class="tag">模拟审核</span><p class="muted">文字资料用于演示审核流程，不代表证件真实性已核验。</p>${q?`<div class="reportTarget"><b>${q.status}</b><p>${escapeHTML(q.type)} · ${escapeHTML(q.number)}</p><p>有效期至 ${escapeHTML(q.expiry)}</p>${q.reason?`<p>驳回原因：${escapeHTML(q.reason)}</p>`:''}</div>`:''}${!q||q.status==='已驳回'?`<form id="qualificationForm"><label class="reportField">申请类目<select><option>专项许可类目（演示）</option></select></label><label class="reportField">资质类型<input id="qualificationType" required value="${escapeHTML(q?.type||'')}" placeholder="填写资质类型"></label><label class="reportField">证件编号<input id="qualificationNumber" required value="${escapeHTML(q?.number||'')}"></label><label class="reportField">有效期至<input id="qualificationExpiry" type="date" required value="${q?.expiry||''}"></label><p id="qualificationError" role="alert"></p><button class="primary" type="submit">提交申请</button></form>`:''}<div class="orderActions"><button id="qualificationBack">${returnEditor?'返回商品编辑':'返回经营资质'}</button>${q?.status==='待审核'?'<button id="qualificationReview">模拟审核</button>':''}</div>`);$('qualificationBack').onclick=()=>{if(returnEditor)drawProductEditor();else{$('dialog').close();openSeller('qualifications');}};if($('qualificationForm'))$('qualificationForm').onsubmit=e=>{e.preventDefault();const type=$('qualificationType').value.trim(),number=$('qualificationNumber').value.trim(),expiry=$('qualificationExpiry').value;if(!type||!number||expiry<new Date().toLocaleDateString('sv-SE')){$('qualificationError').textContent='请填写完整资料，有效期不得早于今天';return;}qualificationRecord={type,number,expiry,status:'待审核'};showQualificationForm(returnEditor);};if($('qualificationReview'))$('qualificationReview').onclick=()=>{modal('专项资质 · 模拟审核',`<p>${escapeHTML(q.type)} · ${escapeHTML(q.number)}</p><p>有效期至 ${escapeHTML(q.expiry)}</p><label class="reportField">驳回原因（驳回时必填）<textarea id="qualificationRejectReason"></textarea></label><p id="qualificationReviewError" role="alert"></p><div class="orderActions"><button id="qualificationReject">驳回</button><button id="qualificationApprove" class="primary">通过（模拟）</button></div>`);$('qualificationApprove').onclick=()=>{q.status='已通过';q.reason='';showQualificationForm(returnEditor);};$('qualificationReject').onclick=()=>{const reason=$('qualificationRejectReason').value.trim();if(!reason){$('qualificationReviewError').textContent='请填写驳回原因';return;}q.status='已驳回';q.reason=reason;showQualificationForm(returnEditor);};};}
const textApplicationBase=showApplicationPage;showApplicationPage=function(kind){textApplicationBase(kind);if(kind==='pending'&&shopApplication?.status==='PENDING'){applicationPage.querySelector('.applicationActions').insertAdjacentHTML('beforeend','<button id="reviewTextApplication">模拟管理员审核</button>');$('reviewTextApplication').onclick=()=>{modal('开店申请 · 模拟审核',`${applicationSummary(shopApplication)}<label class="reportField">驳回原因（驳回时必填）<textarea id="applicationRejectReason"></textarea></label><p id="applicationReviewError" role="alert"></p><div class="orderActions"><button id="rejectTextApplication">驳回</button><button id="approveTextApplication" class="primary">通过（模拟）</button></div>`);$('approveTextApplication').onclick=()=>{shopApplication.status='APPROVED';$('dialog').close();openApproved();};$('rejectTextApplication').onclick=()=>{const reason=$('applicationRejectReason').value.trim();if(!reason){$('applicationReviewError').textContent='请填写驳回原因';return;}shopApplication.status='REJECTED';shopApplication.reason=reason;$('dialog').close();exitApplication();showShopApplication();};};}};
const textShopApplicationBase=showShopApplication;showShopApplication=function(){if(shopApplication?.status==='REJECTED'){modal('开店申请已驳回',`<span class="tag">模拟审核</span>${applicationSummary(shopApplication)}<p>驳回原因：${escapeHTML(shopApplication.reason)}</p><button id="reapplyTextShop" class="primary">修改后重新申请</button>`);$('reapplyTextShop').onclick=()=>{const old=shopApplication;shopApplication=null;textShopApplicationBase();const f=$('shopApplyForm');f.elements.shopName.value=old.name;f.elements.subject.value=old.subject;f.elements.license.value=old.license;};return;}textShopApplicationBase();};
